; ===========================================================================
;  MTKPLAY - standalone replayer for MSXTRACK songs (.MTK), for games
;  and demos. GENERATED by tools/gen_replayer.py from the tracker's own
;  engine (src/player_core.asm) - edit those, not this file.
;
;  Usage:
;      MTK_RAM equ 0E000h          ; MTK_RAMSIZE (175) bytes of RAM
;              include "mtkplay.asm"
;
;      ld hl,song : call mtk_init  ; Z = ok
;      xor a      : call mtk_start ; play from position 0
;      ...and call mtk_frame once per frame from your interrupt hook
;      (H.TIMI), e.g.  hook: call mtk_frame : ret
;
;      ld a,10 : ld b,49 : ld c,2 : call mtk_sfx   ; instrument 10 as a
;                                   ; sound effect at C-5 on channel C
;  Calls
;      mtk_init      HL = .MTK file              -> Z ok / NZ bad file
;      mtk_start     A = order position          music on (loops)
;      mtk_stop                                  music off
;      mtk_frame     once per frame (interrupt)  plays and writes the PSG
;      mtk_sfx       A = instrument, B = note, C = channel
;      mtk_sfx_stop                              end the sound effect
;      mtk_sfx_bank  HL = .MTK file               effects from another file
;  Readable state
;      mtk_PL_PLAYING (0 = stopped), mtk_PL_ORDPOS, mtk_PL_ROW, mtk_SFX_ON
;
;  Notes
;  - The song data is only read, so it can stay in ROM.
;  - mtk_init/start/stop/sfx briefly disable interrupts and return with
;    them enabled. mtk_frame and the hook may use all registers; the MSX
;    BIOS saves them before calling H.TIMI.
;  - Port A0h/A1h only; register 7 keeps the MSX I/O bits (10xxxxxx).
;  - Labels all start with mtk_ / MTK_. Plain Z80 syntax (built and tested
;    with pasmo). About 2.3KB of code and tables.
; ===========================================================================
